    def is_prime(n):
        """Helper function to check if a number is prime."""
        if n < 2:
            return False
        for i in range(2, int(n**0.5) + 1):
            if n % i == 0:
                return False
        return True

    # Generate all primes less than 100
    primes = [x for x in range(2, 100) if is_prime(x)]

    # Check all combinations of three distinct primes
    for i in range(len(primes)):
        for j in range(i, len(primes)):  # Allow repetition of primes
            for k in range(j, len(primes)):  # Allow repetition of primes
                if primes[i] * primes[j] * primes[k] == a:
                    return True

    return False
